// Parsea el evento de Calendly creado en Google Calendar.
const ev = $json;
const desc = String(ev.description || '');
const summary = String(ev.summary || '');

// Teléfono: primera secuencia de 8+ dígitos en la descripción.
let telefono = null;
const mTel = desc.replace(/\s/g, ' ').match(/(\+?\d[\d\s().-]{7,}\d)/);
if (mTel) telefono = mTel[1].replace(/\D/g, '');
const to = telefono ? ('+' + telefono) : '';

// Email
let email = null;
const mMail = desc.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
if (mMail) email = mMail[0];

// Nombre: línea 'Name:' de Calendly o, si no, el título del evento.
let nombre = null;
const mName = desc.match(/Name:\s*(.+)/i);
if (mName) nombre = mName[1].trim();
if (!nombre && summary) nombre = summary;

// URLs de cancelar / reprogramar (Calendly las pone en la descripción)
const mCancel = desc.match(/Cancel:\s*(\S+)/i);
const mResch  = desc.match(/Reschedule:\s*(\S+)/i);

const fechaISO = ev.start?.dateTime || ev.start?.date || null;

function fmt(iso) {
  if (!iso) return '';
  try {
    return new Date(iso).toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', dateStyle: 'full', timeStyle: 'short' });
  } catch (e) { return iso; }
}
const fecha_hora_texto = fmt(fechaISO);

const mensaje = `¡Hola${nombre ? ' ' + nombre : ''}! Ahí vi que agendaste 🙌 Te confirmo la reunión para el ${fecha_hora_texto}. Si necesitás cambiar algo, avisame. ¡Gracias!`;

return [{ json: {
  nombre: nombre || null,
  telefono: telefono || null,
  email: email || null,
  fecha_hora: fechaISO,
  evento: summary || null,
  cancel_url: mCancel ? mCancel[1] : null,
  reschedule_url: mResch ? mResch[1] : null,
  to,
  fecha_hora_texto,
  mensaje
} }];

